const canvas = document.createElement('canvas');
canvas.width = 1200;
canvas.height = 1800;
const ctx = canvas.getContext('2d');

// 1. Background
ctx.fillStyle = '#fdfaf5'; // Soft cream
ctx.fillRect(0, 0, 1200, 1800);

// 2. Subtle Sun
const grad = ctx.createRadialGradient(600, 300, 0, 600, 300, 400);
grad.addColorStop(0, 'rgba(235, 77, 75, 0.4)');
grad.addColorStop(1, 'rgba(235, 77, 75, 0)');
ctx.fillStyle = grad;
ctx.beginPath();
ctx.arc(600, 300, 400, 0, Math.PI * 2);
ctx.fill();

// 3. Mountains (Minimalist)
ctx.fillStyle = 'rgba(47, 53, 66, 0.05)';
ctx.beginPath();
ctx.moveTo(0, 1200);
ctx.lineTo(300, 800);
ctx.lineTo(600, 1200);
ctx.lineTo(900, 900);
ctx.lineTo(1200, 1200);
ctx.lineTo(1200, 1800);
ctx.lineTo(0, 1800);
ctx.fill();

// 4. Horses (Year of the Horse 2026)
function drawHorse(x, y, scale, flip = false) {
    ctx.save();
    ctx.translate(x, y);
    if (flip) ctx.scale(-1, 1);
    ctx.scale(scale, scale);
    ctx.fillStyle = '#2f3542';
    // Abstract body
    ctx.beginPath();
    ctx.ellipse(0, 0, 40, 20, 0, 0, Math.PI * 2);
    // Neck & Head
    ctx.moveTo(30, -5);
    ctx.quadraticCurveTo(50, -30, 45, -50);
    ctx.lineTo(60, -45);
    ctx.lineTo(55, -25);
    // Legs
    ctx.moveTo(-20, 10); ctx.lineTo(-25, 40);
    ctx.moveTo(-10, 15); ctx.lineTo(-12, 45);
    ctx.moveTo(10, 15); ctx.lineTo(12, 45);
    ctx.moveTo(20, 10); ctx.lineTo(25, 40);
    ctx.fill();
    ctx.restore();
}
drawHorse(1000, 1650, 1.2);
drawHorse(850, 1680, 0.8, true);

// 5. Text - Using custom fonts if possible, else falling back
ctx.textAlign = 'center';
ctx.fillStyle = '#1e272e';

// Title
ctx.font = 'bold 54px serif';
ctx.fillText('조승환 부장님, 여승주 부장님!!', 600, 650);

// Body
ctx.font = '32px serif';
const lines = [
    '2026년 병오년 새해 복 많이 받으십시오.',
    '새해에는 하시는 일 모두 건승하시길 진심으로 기원합니다.',
    '',
    '건강과 가족이 무엇보다도 제일 중요하니,',
    '올 한 해 항상 건강하시고 가정에 화목이 깃들길 바랍니다.',
    '',
    '조만간 다시 다 같이 일할 수 있는 기회가 생기면 좋겠습니다!'
];
lines.forEach((line, i) => {
    ctx.fillText(line, 600, 750 + (i * 60));
});

// Sender
ctx.font = 'bold 36px serif';
ctx.fillText('박찬주 배상', 600, 1300);

// 6. Logos (Placeholder modern style)
const logos = ['CSWind', 'Microsoft', 'AWS', 'Azure', 'Gemini'];
ctx.font = '24px sans-serif';
const startX = 600 - (logos.length * 100) / 2;
logos.forEach((logo, i) => {
    ctx.fillText(logo, startX + (i * 120), 1450);
});

// 7. Accents (Mae-hwa)
function drawBlossom(x, y) {
    ctx.fillStyle = '#eb4d4b';
    for (let i = 0; i < 5; i++) {
        ctx.beginPath();
        const ang = (i * Math.PI * 2) / 5;
        ctx.arc(x + Math.cos(ang) * 10, y + Math.sin(ang) * 10, 8, 0, Math.PI * 2);
        ctx.fill();
    }
    ctx.fillStyle = '#f0932b';
    ctx.beginPath();
    ctx.arc(x, y, 4, 0, Math.PI * 2);
    ctx.fill();
}
drawBlossom(100, 400);
drawBlossom(150, 450);
drawBlossom(1100, 200);

// Save output
const data = canvas.toDataURL('image/png');
A2UI.saveMedia(data, 'new_year_card_2026.png');

