const canvas = document.createElement('canvas');
canvas.width = 1200;
canvas.height = 1800;
const ctx = canvas.getContext('2d');

// 1. Background (Hanji texture like)
ctx.fillStyle = '#f9f6f2'; 
ctx.fillRect(0, 0, 1200, 1800);

// Subtle noise texture
for (let i = 0; i < 10000; i++) {
    ctx.fillStyle = `rgba(0,0,0,${Math.random() * 0.02})`;
    ctx.fillRect(Math.random() * 1200, Math.random() * 1800, 1, 1);
}

// 2. Sun (Top Center)
const sunGrad = ctx.createLinearGradient(0, 50, 0, 250);
sunGrad.addColorStop(0, '#f0932b');
sunGrad.addColorStop(1, '#eb4d4b');
ctx.fillStyle = sunGrad;
ctx.beginPath();
ctx.arc(600, 150, 100, 0, Math.PI * 2);
ctx.fill();

// 3. Pavilion (Simple Silhouette)
function drawPavilion(x, y, scale) {
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(scale, scale);
    ctx.fillStyle = '#2d3436';
    // Roof
    ctx.beginPath();
    ctx.moveTo(-100, 0);
    ctx.quadraticCurveTo(0, -50, 100, 0);
    ctx.lineTo(80, 10);
    ctx.quadraticCurveTo(0, -30, -80, 10);
    ctx.closePath();
    ctx.fill();
    // Pillars
    ctx.fillRect(-60, 10, 10, 80);
    ctx.fillRect(50, 10, 10, 80);
    ctx.fillRect(-20, 10, 10, 80);
    ctx.fillRect(10, 10, 10, 80);
    // Base
    ctx.fillRect(-80, 90, 160, 20);
    ctx.restore();
}
drawPavilion(200, 200, 0.6);
drawPavilion(1000, 1600, 0.5);

// 4. Cranes
function drawCrane(x, y, scale, flip = false) {
    ctx.save();
    ctx.translate(x, y);
    if (flip) ctx.scale(-1, 1);
    ctx.scale(scale, scale);
    ctx.strokeStyle = '#2d3436';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(0,0);
    ctx.bezierCurveTo(20, -10, 40, -40, 60, -20); // Wing
    ctx.moveTo(0,0);
    ctx.bezierCurveTo(-20, -10, -40, 20, -60, 0); // Tail
    ctx.moveTo(0,0);
    ctx.lineTo(10, 30); // Legs
    ctx.stroke();
    ctx.restore();
}
drawCrane(300, 100, 0.8);
drawCrane(900, 120, 0.7, true);

// 5. Plum Blossoms (Mae-hwa)
function drawBranch(x, y, len, ang) {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(ang);
    ctx.strokeStyle = '#4b4b4b';
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.moveTo(0,0);
    ctx.quadraticCurveTo(len/2, 20, len, 0);
    ctx.stroke();

    // Flowers along the branch
    for (let i = 0; i < 5; i++) {
        const px = (i / 4) * len;
        const py = Math.sin((i / 4) * Math.PI) * 10;
        ctx.fillStyle = '#eb4d4b';
        ctx.beginPath();
        ctx.arc(px, py, 12, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#f9ca24';
        ctx.beginPath();
        ctx.arc(px, py, 3, 0, Math.PI * 2);
        ctx.fill();
    }
    ctx.restore();
}
drawBranch(50, 500, 300, Math.PI / 6);
drawBranch(1150, 400, -250, -Math.PI / 8);

// 6. Horses (Year of the Horse)
drawHorse(800, 1700, 1.5);
drawHorse(1000, 1720, 1.0, true);

// 7. Corrected Text
ctx.textAlign = 'center';
ctx.textBaseline = 'middle';
ctx.fillStyle = '#1e272e';

// Name Titles
ctx.font = 'bold 50px serif';
ctx.fillText('조승환 부장님, 여승주 부장님!!', 600, 500);

// Main Body
ctx.font = '34px serif';
const bodyLines = [
    '2026년 병오년 새해 복 많이 받으시고',
    '새해에는 하시는 일 모두 건승하시길 기원합니다.',
    '',
    '건강과 가족이 무엇보다도 제일 중요하니',
    '항상 건강하시고 가정에 화목이 깃들길 기원합니다.',
    '',
    '조만간 다시 다 같이 일할 수 있는 기회가 생기면 좋겠네요!'
];
bodyLines.forEach((line, i) => {
    ctx.fillText(line, 600, 650 + (i * 65));
});

// Signature
ctx.font = 'bold 40px serif';
ctx.fillText('박찬주 배상', 600, 1200);

// 8. Logos
const logoY = 1400;
ctx.font = 'bold 28px sans-serif';
ctx.fillStyle = '#4b4b4b';
ctx.fillText('CSWind', 200, logoY);
ctx.fillText('Microsoft', 400, logoY);
ctx.fillText('aws', 600, logoY);
ctx.fillText('Azure', 800, logoY);
ctx.fillText('Gemini', 1000, logoY);

// Add some graphic symbols near logos
ctx.fillStyle = '#f39c12'; ctx.fillRect(350, logoY-10, 15, 15);
ctx.fillStyle = '#e74c3c'; ctx.fillRect(370, logoY-10, 15, 15);
ctx.fillStyle = '#2ecc71'; ctx.fillRect(350, logoY+10, 15, 15);
ctx.fillStyle = '#3498db'; ctx.fillRect(370, logoY+10, 15, 15);

// 9. Save as PNG
const pngData = canvas.toDataURL('image/png');
A2UI.saveMedia(pngData, 'corrected_new_year_card.png');

